/* SPDX-License-Identifier: GPL-2.0-only
 * Host test of starbite/sbos/kern/tzdb.c (Track A time zones) and ui/sh_timefmt.h (12 / 24-hour text):
 *   sh starbite/sbos/kern/host/tzdb-test.sh        (build.sh runs it on a native aarch64 host)
 * Checks:
 *   - every zone's offset in January and July 2027 against zoneinfo (tzdb-expect.inc, generated by Python);
 *   - every DST transition of 2026 and 2027 (EU, US, AU, NZ) at its exact second: the old offset one second before,
 *     the new one at it, and no other change in a 15-minute sweep of both years;
 *   - local civil time across a few transitions (the hour that repeats, the hour that is skipped);
 *   - the stable ids (distinct, found again);
 *   - the time text: 00:05 -> "12:05 AM", 12:00 -> "12:00 PM", 9:41 -> "9:41" / "09:41".
 * Exit status 0 = all passed. */
#include <stdio.h>
#include <string.h>
#include "tzdb.h"
#include "../../ui/sh_timefmt.h"
#include "tzdb-expect.inc"

static int fails, checks;
#define CHECK(c, ...)                                                                                                  \
    do {                                                                                                               \
        checks++;                                                                                                      \
        if (!(c)) {                                                                                                    \
            fails++;                                                                                                   \
            printf("FAIL %s:%d: ", __FILE__, __LINE__);                                                                \
            printf(__VA_ARGS__);                                                                                       \
            printf("\n");                                                                                              \
        }                                                                                                              \
    } while (0)

static int find(const char *name)
{
    for (int i = 0; i < tzdb_n; ++i)
        if (!strcmp(tzdb[i].name, name))
            return i;
    return -1;
}

static void text(int h, int m, int h24, int ampm, const char *want)
{
    char b[16];
    memset(b, 'x', sizeof b);
    int n = sh_fmt_time(b, h, m, h24, ampm);
    CHECK(!strcmp(b, want) && n == (int)strlen(want), "time text %02d:%02d h24 %d ampm %d: \"%s\", want \"%s\"", h, m,
          h24, ampm, b, want);
}

static void civil(const char *z, long long utc, int y, int mo, int d, int h, int mi, const char *abbr)
{
    struct tz_time l;
    tzdb_local(find(z), utc, &l);
    CHECK(l.y == y && l.mo == mo && l.d == d && l.h == h && l.mi == mi && !strcmp(l.abbr, abbr),
          "%s at %lld: %04d-%02d-%02d %02d:%02d %s, want %04d-%02d-%02d %02d:%02d %s", z, utc, l.y, l.mo, l.d, l.h, l.mi,
          l.abbr, y, mo, d, h, mi, abbr);
}

int main(void)
{
    /* the table: every zone checked, every zone in it */
    int nof = (int)(sizeof OFFS / sizeof OFFS[0]), ntr = (int)(sizeof TRANS / sizeof TRANS[0]);
    CHECK(nof == tzdb_n, "zoneinfo checked %d zones, the table has %d", nof, tzdb_n);
    CHECK(tzdb_n >= 55 && tzdb_n <= 80, "about 60 zones: %d", tzdb_n);
    int groups[TZG_N] = { 0 };
    for (int i = 0; i < tzdb_n; ++i) {
        groups[tzdb[i].group]++;
        CHECK(tzdb[i].city[0] && tzdb[i].std[0] && tzdb[i].dst[0], "zone %d has its names", i);
    }
    for (int g = 0; g < TZG_N; ++g)
        CHECK(groups[g] >= 5, "region %s has %d zones", tzdb_group_name[g], groups[g]);
    CHECK(!strcmp(tzdb[tzdb_home()].name, "Europe/Helsinki"), "the home zone is Helsinki");

    /* offsets: mid-January and mid-July 2027 */
    const long long jan = 1799971200LL, jul = 1815609600LL;   /* 2027-01-15, 2027-07-15 00:00 */
    for (int k = 0; k < nof; ++k) {
        int i = find(OFFS[k].z);
        CHECK(i >= 0, "%s not in the table", OFFS[k].z);
        if (i < 0)
            continue;
        CHECK(tzdb_offset(i, jan) == OFFS[k].jan, "%s in January: %d, want %d", OFFS[k].z, tzdb_offset(i, jan), OFFS[k].jan);
        CHECK(tzdb_offset(i, jul) == OFFS[k].jul, "%s in July: %d, want %d", OFFS[k].z, tzdb_offset(i, jul), OFFS[k].jul);
    }

    /* the transitions, to the second */
    for (int k = 0; k < ntr; ++k) {
        int i = find(TRANS[k].z);
        CHECK(i >= 0, "%s not in the table", TRANS[k].z);
        if (i < 0)
            continue;
        int b = tzdb_offset(i, TRANS[k].t - 1), a = tzdb_offset(i, TRANS[k].t);
        CHECK(b == TRANS[k].before && a == TRANS[k].after, "%s at %lld: %d -> %d, want %d -> %d", TRANS[k].z,
              TRANS[k].t, b, a, TRANS[k].before, TRANS[k].after);
    }
    /* nothing else changes: a 15-minute sweep of 2026 and 2027 (Vancouver from 2026-03-09, as the expectations) */
    const long long y0 = 1767225600LL, y1 = 1830297600LL;                              /* 2026-01-01, 2028-01-01 */
    for (int i = 0; i < tzdb_n; ++i) {
        long long t = !strcmp(tzdb[i].name, "America/Vancouver") ? 1773014400LL : y0;
        int o = tzdb_offset(i, t), seen = 0, expect = 0;
        for (int k = 0; k < ntr; ++k)
            expect += !strcmp(TRANS[k].z, tzdb[i].name);
        for (; t < y1; t += 900) {
            int n = tzdb_offset(i, t + 900);
            if (n != o)
                seen++;
            o = n;
        }
        CHECK(seen == expect, "%s: %d changes in 2026-2027, zoneinfo has %d", tzdb[i].name, seen, expect);
    }

    /* local civil time across the boundaries */
    civil("Europe/Helsinki", 1774745999LL, 2026, 3, 29, 2, 59, "EET");      /* 02:59:59 EET, then 04:00 EEST */
    civil("Europe/Helsinki", 1774746000LL, 2026, 3, 29, 4, 0, "EEST");
    civil("Europe/Helsinki", 1792889999LL, 2026, 10, 25, 3, 59, "EEST");    /* 03:59:59 EEST, then 03:00 EET again */
    civil("Europe/Helsinki", 1792890000LL, 2026, 10, 25, 3, 0, "EET");
    civil("America/New_York", 1772953199LL, 2026, 3, 8, 1, 59, "EST");      /* 01:59:59 EST, then 03:00 EDT */
    civil("America/New_York", 1772953200LL, 2026, 3, 8, 3, 0, "EDT");
    civil("America/New_York", 1793512800LL, 2026, 11, 1, 1, 0, "EST");      /* the second 01:00 */
    civil("Australia/Sydney", 1791043200LL, 2026, 10, 4, 3, 0, "AEDT");     /* 02:00 AEST -> 03:00 AEDT */
    civil("Australia/Sydney", 1806767999LL, 2027, 4, 4, 2, 59, "AEDT");     /* 02:59:59 AEDT, then 02:00 AEST */
    civil("Australia/Sydney", 1806768000LL, 2027, 4, 4, 2, 0, "AEST");
    civil("Pacific/Auckland", 1790431200LL, 2026, 9, 27, 3, 0, "NZDT");
    civil("Pacific/Auckland", 1821880799LL, 2027, 9, 26, 1, 59, "NZST");
    /* 2027-01-15 12:00 UTC */
    civil("Asia/Kolkata", 1800014400LL, 2027, 1, 15, 17, 30, "IST");
    civil("Asia/Kathmandu", 1800014400LL, 2027, 1, 15, 17, 45, "+0545");
    civil("America/St_Johns", 1800014400LL, 2027, 1, 15, 8, 30, "NST");
    civil("Pacific/Tongatapu", 1800014400LL, 2027, 1, 16, 1, 0, "+13");     /* the next day already */
    civil("Pacific/Honolulu", 1800014400LL, 2027, 1, 15, 2, 0, "HST");

    /* the stable ids */
    for (int i = 0; i < tzdb_n; ++i) {
        CHECK(tzdb_id(i) && tzdb_by_id(tzdb_id(i)) == i, "%s: its id finds it again", tzdb[i].name);
        for (int j = 0; j < i; ++j)
            CHECK(tzdb_id(i) != tzdb_id(j), "%s and %s share an id", tzdb[i].name, tzdb[j].name);
    }
    CHECK(tzdb_by_id(0x12345) < 0 || tzdb_id(tzdb_by_id(0x12345)) == 0x12345, "an unknown id finds nothing");

    /* the time text */
    text(0, 5, 0, 1, "12:05 AM");
    text(0, 5, 0, 0, "12:05");
    text(0, 5, 1, 1, "00:05");
    text(12, 0, 0, 1, "12:00 PM");
    text(12, 0, 1, 0, "12:00");
    text(9, 41, 0, 0, "9:41");
    text(9, 41, 0, 1, "9:41 AM");
    text(9, 41, 1, 0, "09:41");
    text(21, 5, 0, 1, "9:05 PM");
    text(21, 5, 1, 1, "21:05");
    text(23, 59, 0, 1, "11:59 PM");
    text(11, 59, 0, 1, "11:59 AM");
    text(13, 0, 0, 0, "1:00");
    text(10, 30, 0, 0, "10:30");

    printf("tzdb test: %d checks, %d failed (%d zones, %d transitions)\n", checks, fails, tzdb_n, ntr);
    return fails != 0;
}
